--
-- Triggers `payment`
--
DELIMITER $$
CREATE TRIGGER `after_payment_insert` AFTER INSERT ON `payment` FOR EACH ROW BEGIN
    INSERT INTO auditpayment (
        paymentId, transactNo, actionType, actionDate, performedBy, oldValues, newValues
    )
    VALUES (
        NEW.paymentId,
        NEW.transactNo,
        'INSERT',
        CURRENT_TIMESTAMP,
        @current_user_id, -- Use the session variable for the user
        NULL,
        CONCAT(
            'New Payment Details - Transact No: ', NEW.transactNo, ', Title: ', NEW.paymentTitle, 
            ', Type: ', NEW.paymentType, ', Amount: ₱', NEW.amount, ', Status: ', NEW.paymentStatus
        )
    );
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `after_payment_update` AFTER UPDATE ON `payment` FOR EACH ROW BEGIN
    DECLARE currentStatus VARCHAR(50);
    DECLARE paymentCount INT;
    DECLARE bookingId INT;
    DECLARE current_user_id INT; -- Declare a user session variable if needed
    
    -- Fetch the current booking status and booking ID
    SELECT b.bookingId, b.status
    INTO bookingId, currentStatus
    FROM booking b
    WHERE b.transactNo = NEW.transactNo;

    -- Count the number of approved payments for this transaction
    SELECT COUNT(*)
    INTO paymentCount
    FROM payment
    WHERE transactNo = NEW.transactNo AND paymentStatus = 'Approved';

    -- If this is the first approved payment, update the booking status
    IF paymentCount = 1 AND currentStatus != 'Confirmed' THEN
        UPDATE booking
        SET status = 'Confirmed'
        WHERE transactNo = NEW.transactNo; -- Use transactNo here instead of bookingId
    END IF;

    -- Insert audit entry for the payment update
    INSERT INTO auditpayment (
        paymentId, 
        transactNo, 
        actionType, 
        actionDate, 
        performedBy, 
        oldValues, 
        newValues
    )
    VALUES (
        OLD.paymentId,
        OLD.transactNo,
        'UPDATE',
        CURRENT_TIMESTAMP,
        current_user_id, -- Use the session variable for the user if available
        CONCAT(
            'Old Payment Details - Transact No: ', OLD.transactNo, ', Title: ', OLD.paymentTitle, 
            ', Type: ', OLD.paymentType, ', Amount: ₱', OLD.amount, ', Status: ', OLD.paymentStatus
        ),
        CONCAT(
            'New Payment Details - Transact No: ', NEW.transactNo, ', Title: ', NEW.paymentTitle, 
            ', Type: ', NEW.paymentType, ', Amount: ₱', NEW.amount, ', Status: ', NEW.paymentStatus
        )
    );
END
$$
DELIMITER ;

